package test.de.itemis.mps.editor.celllayout.editor;

/*Generated by MPS */

import org.junit.jupiter.api.Test;
import de.itemis.mps.editor.celllayout.layout.IndentLayout;
import de.itemis.mps.editor.celllayout.boxmodel.Size;
import org.junit.Assert;
import de.itemis.mps.editor.celllayout.layout.VerticalLayout;
import de.itemis.mps.editor.celllayout.layout.HorizontalLayout;

public class IndentLayoutNoWrap_Test {
  @Test
  public void test_wrapsBeforeEarlierWordWhenNextWordIsNoWrap() throws Exception {
    IndentLayout layout = new IndentLayout(0);
    LayoutProbeContainer line = new LayoutProbeContainer(layout);
    LayoutProbeLeaf a = new LayoutProbeLeaf(30, 10);
    LayoutProbeLeaf b = new LayoutProbeLeaf(30, 10);
    LayoutProbeLeaf c = new LayoutProbeLeaf(30, 10);
    c.noWrap = true;
    line.add(a);
    line.add(b);
    line.add(c);
    layout.layout(line, Size.limitedWidth(100));
    Assert.assertEquals("a b [no-wrap c] at width 100: a should stay on the first line", 0, a.y);
    Assert.assertEquals("a b [no-wrap c] at width 100: b should start the second line", 10, b.y);
    Assert.assertEquals("a b [no-wrap c] at width 100: c should not start a wrapped line", 10, c.y);
  }
  @Test
  public void test_doesNotWrapWhenOnlyBreakIsBeforeNoWrapWord() throws Exception {
    IndentLayout layout = new IndentLayout(0);
    LayoutProbeContainer line = new LayoutProbeContainer(layout);
    LayoutProbeLeaf a = new LayoutProbeLeaf(60, 10);
    LayoutProbeLeaf b = new LayoutProbeLeaf(60, 10);
    b.noWrap = true;
    line.add(a);
    line.add(b);
    layout.layout(line, Size.limitedWidth(100));
    Assert.assertEquals("a [no-wrap b] at width 100: b should not start a wrapped line", 0, b.y);
    Assert.assertEquals("a [no-wrap b] at width 100: b should follow a on the same line", 70, b.x);
  }
  @Test
  public void test_wrapsInsideNoWrapCollectionButNotBeforeIt() throws Exception {
    IndentLayout layout = new IndentLayout(0);
    LayoutProbeContainer line = new LayoutProbeContainer(layout);
    LayoutProbeLeaf a = new LayoutProbeLeaf(30, 10);
    LayoutProbeLeaf x = new LayoutProbeLeaf(30, 10);
    LayoutProbeContainer noWrapCollection = new LayoutProbeContainer(layout);
    noWrapCollection.noWrap = true;
    LayoutProbeLeaf b = new LayoutProbeLeaf(30, 10);
    LayoutProbeLeaf c = new LayoutProbeLeaf(30, 10);
    noWrapCollection.add(b);
    noWrapCollection.add(c);
    line.add(a);
    line.add(x);
    line.add(noWrapCollection);
    // layout() would fail on the nested collection: it adjusts the bounds of the collection through an EditorCellBoxModel,
    // which the probe containers don't have. The preferred size shows where the line wrapped instead.
    Size size = layout.getPreferredInnerSize(line, Size.limitedWidth(120));
    Assert.assertEquals("a x [no-wrap collection: b c] at width 120: the first line should be a x b (width 110), wrapped before c", 110, size.getWidth());
    Assert.assertEquals("a x [no-wrap collection: b c] at width 120: should be laid out on two lines", 20, size.getHeight());
  }
  @Test
  public void test_wrapsInsideNoWrapCollection() throws Exception {
    IndentLayout layout = new IndentLayout(0);
    LayoutProbeContainer line = new LayoutProbeContainer(layout);
    line.noWrap = true;
    LayoutProbeLeaf a = new LayoutProbeLeaf(60, 10);
    LayoutProbeLeaf b = new LayoutProbeLeaf(60, 10);
    line.add(a);
    line.add(b);
    layout.layout(line, Size.limitedWidth(100));
    Assert.assertEquals("no-wrap collection [a b] laid out at width 100: b should start the second line", 10, b.y);
  }
  @Test
  public void test_wrapsInsideCollectionWithNoWrapAncestor() throws Exception {
    LayoutProbeContainer ancestor = new LayoutProbeContainer(new VerticalLayout());
    ancestor.noWrap = true;
    IndentLayout layout = new IndentLayout(0);
    LayoutProbeContainer line = new LayoutProbeContainer(layout);
    LayoutProbeLeaf a = new LayoutProbeLeaf(60, 10);
    LayoutProbeLeaf b = new LayoutProbeLeaf(60, 10);
    line.add(a);
    line.add(b);
    ancestor.add(line);
    layout.layout(line, Size.limitedWidth(100));
    Assert.assertEquals("[a b] inside a no-wrap ancestor, laid out at width 100: b should start the second line", 10, b.y);
  }
  @Test
  public void test_doesNotWrapInsideHorizontalCollection() throws Exception {
    IndentLayout layout = new IndentLayout(0);
    LayoutProbeContainer line = new LayoutProbeContainer(layout);
    LayoutProbeLeaf a = new LayoutProbeLeaf(30, 10);
    LayoutProbeContainer horizontal = new LayoutProbeContainer(new HorizontalLayout());
    LayoutProbeLeaf b = new LayoutProbeLeaf(30, 10);
    LayoutProbeLeaf c = new LayoutProbeLeaf(30, 10);
    horizontal.add(b);
    horizontal.add(c);
    line.add(a);
    line.add(horizontal);
    // Checks the preferred size: layout() of a horizontal collection needs the box model of an editor cell, which the
    // probe containers don't have. A break between b and c would make the first line a b, 70 wide.
    Size size = layout.getPreferredInnerSize(line, Size.limitedWidth(80));
    Assert.assertEquals("a [horizontal: b c] at width 80: the horizontal collection should move to the second line as a whole", 60, size.getWidth());
    Assert.assertEquals("a [horizontal: b c] at width 80: the layout should have two lines", 20, size.getHeight());
  }
}
